const ASSETS_DIR = path.join(__dirname, '..', 'assets', 'ui-references');
const URL_PREFIX = '/ui-references';

function getById(id) {
  const entry = LIBRARY[id];
  if (!entry) return null;
  return {
    id,
    url: `${URL_PREFIX}/${entry.file}`,
    alt: entry.alt,
  };
}

// Returns all IDs whose `skills` array contains the target skillId OR the
// wildcard '*' (foundational images that apply to every task). Skill-specific
// results are returned first, followed by wildcards — this ordering surfaces
// the most relevant images at the top of the prompt section.
function getIdsForSkill(skillId) {
  const specific = [];
  const wildcard = [];
  for (const [id, entry] of Object.entries(LIBRARY)) {
    if (skillId && entry.skills.includes(skillId)) {
      specific.push(id);
    } else if (entry.skills.includes('*')) {
      wildcard.push(id);
    }
  }
  return [...specific, ...wildcard];
}

function getAllEntries() {
  return Object.entries(LIBRARY).map(([id, entry]) => ({
    id,
    ...entry,
    url: `${URL_PREFIX}/${entry.file}`,
  }));
}

// Logs a summary at server startup. Missing files are warnings, not errors —
// the graceful fallback on the client handles missing images at render time.
function validateLibrary() {
  const entries = Object.entries(LIBRARY);
  let present = 0;
  let missing = [];
  for (const [id, entry] of entries) {
    const fullPath = path.join(ASSETS_DIR, entry.file);
    if (fs.existsSync(fullPath)) {
      present++;
    } else {
      missing.push(id);
    }
  }
  console.log(`[uiReferenceLibrary] ${present}/${entries.length} references valid`);
  if (missing.length > 0) {
    console.warn(`[uiReferenceLibrary] Missing files for IDs: ${missing.join(', ')}`);
  }
  return { total: entries.length, present, missing };
}

module.exports = {
  LIBRARY,
  ASSETS_DIR,
  URL_PREFIX,
  getById,
  getIdsForSkill,
  getAllEntries,
  validateLibrary,
};

'use strict';

const { filterResponse, enforceReadability } = require('../core/vocabularyFilter');

// filterResponse

describe('filterResponse', () => {
  // Basic level — every substitution in basicSubstitutions.json is applied
  describe('basic level', () => {
    test('replaces "browser" with "internet app"', () => {
      expect(filterResponse('Open your browser.', 'basic')).toBe('Open your internet app.');
    });

    test('leaves "download" unchanged (well-known term, awkward substitution removed)', () => {
      // "download" used to map to "save from the internet" which produced
      // ungrammatical output like "save from the internet it". The substitution
      // was removed because the word is well-known enough for elderly users.
      expect(filterResponse('Please download the file.', 'basic')).toBe(
        'Please download the file.'
      );
    });

    test('replaces "URL" with "web address"', () => {
      expect(filterResponse('Enter the URL in the box.', 'basic')).toBe(
        'Enter the web address in the box.'
      );
    });

    test('replaces basic-only term "spam" with "junk email"', () => {
      expect(filterResponse('That email looks like spam.', 'basic')).toBe(
        'That email looks like junk email.'
      );
    });

    test('replaces "router" with "internet box"', () => {
      expect(filterResponse('Restart your router.', 'basic')).toBe('Restart your internet box.');
    });
  });

  // Intermediate level — only INTERMEDIATE_KEYS subset is applied
  describe('intermediate level', () => {
    test('replaces an intermediate term like "malware"', () => {
      expect(filterResponse('Your computer has malware on it.', 'intermediate')).toBe(
        'Your computer has bad software on it.'
      );
    });

    test('replaces "phishing" with "trick email"', () => {
      expect(filterResponse('Watch out for phishing emails.', 'intermediate')).toBe(
        'Watch out for trick email emails.'
      );
    });

    test('does NOT replace basic-only terms like "spam"', () => {
      const result = filterResponse('That email looks like spam.', 'intermediate');
      expect(result).toBe('That email looks like spam.');
    });

    test('does NOT replace basic-only terms like "browser"', () => {
      const result = filterResponse('Open the browser please.', 'intermediate');
      expect(result).toBe('Open the browser please.');
    });
  });

  // Standard level — no replacements at all
  describe('standard level', () => {
    test('makes no changes to the text', () => {
      const original = 'Open your browser and download the file.';
      expect(filterResponse(original, 'standard')).toBe(original);
    });

    test('returns the original string unchanged', () => {
      const original = 'The cache and firewall settings are fine.';
      expect(filterResponse(original, 'standard')).toBe(original);
    });
  });

  // Whole-word replacement — "browsing" must NOT be touched when targeting "browser"
  describe('whole-word replacement', () => {
    test('does not replace "browsing" when targeting "browser"', () => {
      const result = filterResponse('I was browsing the web.', 'basic');
      expect(result).toBe('I was browsing the web.');
    });

    test('does not replace "cached" when targeting "cache"', () => {
      const result = filterResponse('The cached data is old.', 'intermediate');
      expect(result).toBe('The cached data is old.');
    });

    test('does not replace "downloading" when targeting "download"', () => {
      const result = filterResponse('I am downloading it now.', 'basic');
      expect(result).toBe('I am downloading it now.');
    });
  });

  // Case-insensitive matching
  describe('case-insensitive matching', () => {
    test('replaces "Browser" (capital B) at basic level', () => {
      expect(filterResponse('Open Browser now.', 'basic')).toContain('internet app');
    });

    test('replaces "BROWSER" (all caps) at basic level', () => {
      expect(filterResponse('Open BROWSER now.', 'basic')).toContain('internet app');
    });

    test('replaces "Malware" (capital M) at intermediate level', () => {
      expect(filterResponse('There is Malware here.', 'intermediate')).toContain('bad software');
    });
  });

  // Edge cases for null/empty input
  describe('graceful handling of empty / null input', () => {
    test('returns null when text is null', () => {
      expect(filterResponse(null, 'basic')).toBeNull();
    });

    test('returns undefined when text is undefined', () => {
      expect(filterResponse(undefined, 'basic')).toBeUndefined();
    });

    test('returns empty string unchanged', () => {
      expect(filterResponse('', 'basic')).toBe('');
    });

    test('returns empty string unchanged at standard level', () => {
      expect(filterResponse('', 'standard')).toBe('');
    });
  });
});

// enforceReadability

describe('enforceReadability', () => {
  test('leaves a short sentence (≤20 words) unchanged', () => {
    const short = 'Click the button to save your file.';
    expect(enforceReadability(short)).toBe(short);
  });

  test('splits a long sentence at "and"', () => {
    // 23 words — should be split
    const long =
      'First you need to open the browser and then you need to type the address and press the enter key on your keyboard.';
    const result = enforceReadability(long);
    // Should contain '. ' indicating a split was made
    expect(result).toContain('. ');
    // Original text should not be returned verbatim
    expect(result).not.toBe(long);
  });

  test('splits a long sentence at "but"', () => {
    const long =
      'You can try restarting your computer right now but you should save all of your work before you do that because it might take a while.';
    const result = enforceReadability(long);
    expect(result).toContain('. ');
  });

  test('splits a long sentence at "because"', () => {
    const long =
      'Your screen might be too dark to see clearly because the brightness setting on your monitor has been turned all the way down by someone.';
    const result = enforceReadability(long);
    expect(result).toContain('. ');
  });

  test('does not split a 20-word sentence exactly at the boundary', () => {
    // Exactly 20 words — should NOT be split
    const twenty =
      'You can click on the icon on the desktop to open the program that you want.';
    const wordCount = twenty.trim().split(/\s+/).length;
    expect(wordCount).toBeLessThanOrEqual(20);
    expect(enforceReadability(twenty)).toBe(twenty);
  });

  test('handles null input gracefully', () => {
    expect(enforceReadability(null)).toBeNull();
  });

  test('handles undefined input gracefully', () => {
    expect(enforceReadability(undefined)).toBeUndefined();
  });

  test('handles empty string gracefully', () => {
    expect(enforceReadability('')).toBe('');
  });

  test('capitalizes first letter of each new segment after split', () => {
    const long =
      'You need to open the settings menu on your computer and then scroll down to the display section and change the brightness level.';
    const result = enforceReadability(long);
    // Each segment after a split should start with an uppercase letter
    const segments = result.split('. ');
    segments.forEach(seg => {
      if (seg.length > 0) {
        expect(seg.charAt(0)).toBe(seg.charAt(0).toUpperCase());
      }
    });
  });
});

const path = require('path');
const substitutions = require(path.join(__dirname, '../assets/vocabulary/basicSubstitutions.json'));

// Keys that are considered "intermediate" complexity — a subset of all substitutions.
// These are the most confusing tech terms even for intermediate users.
const INTERMEDIATE_KEYS = [
  'malware',
  'phishing',
  'bandwidth',
  'cache',
  'firewall',
  'cookie',
  'router',
  'Wi-Fi',
  'VPN',
  'two-factor authentication',
  '2FA',
  'encryption',
  'sync',
  'cloud',
  'SSID',
];

/**
 * Build a regex that matches a term as a whole word (case-insensitive).
 * Handles special regex characters in the term.
 */
function buildWordRegex(term) {
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`\\b${escaped}\\b`, 'gi');
}

/**
 * Apply vocabulary substitutions to text.
 * @param {string} text
 * @param {string} vocabLevel  'basic' | 'intermediate' | 'standard'
 * @returns {string}
 */
function filterResponse(text, vocabLevel) {
  if (!text || vocabLevel === 'standard') return text;

  if (vocabLevel !== 'basic' && vocabLevel !== 'intermediate') {
    console.warn(`[vocabularyFilter] Unexpected vocabulary level: "${vocabLevel}". Expected "basic", "intermediate", or "standard".`);
  }

  let result = text;
  const keysToApply = vocabLevel === 'basic'
    ? Object.keys(substitutions)
    : INTERMEDIATE_KEYS;

  for (const term of keysToApply) {
    const replacement = substitutions[term];
    if (!replacement) continue;
    result = result.replace(buildWordRegex(term), replacement);
  }

  return result;
}

/**
 * Split sentences longer than 20 words at natural break points before
 * conjunctions: "and", "but", "or", "because". "so" is intentionally excluded
 * because it is usually phrasal ("so happy", "so tired") — splitting at "so"
 * produces awkward fragments like "she'll be. So happy".
 *
 * Each resulting segment must contain at least MIN_WORDS_PER_SEGMENT words.
 * If a segment would be shorter, the break is skipped (keeping the phrase
 * intact) or the short tail is merged back into the previous segment.
 * @param {string} text
 * @returns {string}
 */
// Each segment from a conjunction split must be at least this many words.
// Raising this from 4 to 6 prevents short-clause splits like
// "it's reliable. And fairly easy to use." — where the tail is grammatically
// valid but reads as an awkward sentence fragment. 6 keeps genuine clauses
// (which are typically 6+ words) while folding short tails back in.
const MIN_WORDS_PER_SEGMENT = 6;

function enforceReadability(text) {
  if (!text) return text;

  // Split on sentence-ending punctuation, preserving the delimiter
  const sentences = text.split(/(?<=[.!?])\s+/);

  const processed = sentences.map(sentence => {
    const words = sentence.trim().split(/\s+/);
    if (words.length <= 20) return sentence;

    // Split at clause-boundary conjunctions only. "so" is excluded above.
    const breakPattern = /\s+(and|but|or|because)\s+/gi;
    const parts = [];
    let lastIndex = 0;
    let match;

    while ((match = breakPattern.exec(sentence)) !== null) {
      const upToBreak = sentence.slice(lastIndex, match.index).trim();
      // Only accept this break if the segment before it is long enough.
      // This prevents awkward fragments like "she'll be. So happy..." when
      // the conjunction is part of a short adjectival phrase.
      const beforeWordCount = upToBreak.split(/\s+/).filter(Boolean).length;
      if (upToBreak && beforeWordCount >= MIN_WORDS_PER_SEGMENT) {
        parts.push(upToBreak);
        // Start the next segment with the conjunction (skip the leading space)
        lastIndex = match.index + 1;
      }
    }

    // Handle the remaining text after the last accepted break
    const tail = sentence.slice(lastIndex).trim();
    if (tail) {
      const tailWordCount = tail.split(/\s+/).filter(Boolean).length;
      if (tailWordCount >= MIN_WORDS_PER_SEGMENT || parts.length === 0) {
        parts.push(tail);
      } else {
        // Merge a short tail back into the previous segment rather than
        // creating a tiny fragment like ". And the grandchildren."
        parts[parts.length - 1] += ' ' + tail;
      }
    }

    if (parts.length <= 1) return sentence; // no breaks found or nothing split

    // Capitalize first letter of each new segment after punctuating previous one.
    // Strip trailing commas/semicolons/whitespace from each part before joining
    // to prevent artifacts like "left side,. Or do you see..." when a segment
    // ends with a comma that collides with the '. ' joiner.
    const joined = parts.map((part, i) => {
      const cleaned = part.replace(/[,;]\s*$/, '').trim();
      if (i === 0) return cleaned;
      // Capitalize first word
      return cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
    }).join('. ');

    // Ensure the joined string ends with a period if it doesn't already have terminal punctuation
    return joined.match(/[.!?]$/) ? joined : joined + '.';
  });

  return processed.join(' ');
}

/**
 * Detect jargon terms still present in text that should have been replaced.
 * Used by the quality tracker to flag jargon that slipped through filtering.
 * @param {string} text - the text to scan (should be the FILTERED response)
 * @param {string} vocabLevel - 'basic' | 'intermediate' | 'standard'
 * @returns {Array<{term: string, replacement: string}>} terms found in the text
 */
function detectJargon(text, vocabLevel) {
  if (!text || vocabLevel === 'standard') return [];
  const found = [];
  const keysToCheck = vocabLevel === 'basic'
    ? Object.keys(substitutions)
    : INTERMEDIATE_KEYS;
  for (const term of keysToCheck) {
    const replacement = substitutions[term];
    if (!replacement) continue;
    if (buildWordRegex(term).test(text)) {
      found.push({ term, replacement });
    }
  }
  return found;
}

module.exports = { filterResponse, enforceReadability, detectJargon };

