1	/**
2	 * feedbackAnalyzer — read end-of-chat feedback and write a short
3	 * "what to do differently next time" note back to the feedback row.
4	 *
5	 * Called fire-and-forget from POST /api/quality/feedback. Never throws
6	 * to the caller — errors are logged and the suggestion column stays
7	 * NULL so the admin page just shows "not yet generated".
8	 */
9	
10	const Anthropic = require('@anthropic-ai/sdk');
11	const { anthropicApiKey } = require('../config');
12	const ConversationFeedback = require('../models/ConversationFeedback');
13	const Conversation = require('../models/Conversation');
14	const Message = require('../models/Message');
15	
16	const MODEL = 'claude-sonnet-4-20250514';
17	const MAX_TRANSCRIPT_MESSAGES = 30;
18	const MAX_TRANSCRIPT_CHARS = 8000;
19	
20	let client = null;
21	function getClient() {
22	  if (!anthropicApiKey) return null;
23	  if (!client) client = new Anthropic({ apiKey: anthropicApiKey });
24	  return client;
25	}
26	
27	function truncateTranscript(messages) {
28	  const recent = messages.slice(-MAX_TRANSCRIPT_MESSAGES);
29	  let total = 0;
30	  const kept = [];
31	  for (let i = recent.length - 1; i >= 0; i--) {
32	    const body = String(recent[i].body || '');
33	    if (total + body.length > MAX_TRANSCRIPT_CHARS) break;
34	    total += body.length;
35	    kept.unshift(recent[i]);
36	  }
37	  return kept;
38	}
39	
40	function formatTranscript(messages) {
41	  return messages
42	    .map((m) => `${m.role === 'user' ? 'USER' : 'ASSISTANT'}: ${m.body}`)
43	    .join('\n\n');
44	}
45	
46	/**
47	 * Generate a suggestion for a single feedback row and persist it.
48	 * @param {string} feedbackId
49	 * @returns {Promise<string|null>} the suggestion text, or null on skip/error
50	 */
51	async function analyze(feedbackId) {
52	  try {
53	    if (process.env.MOCK_MODE === 'true') return null;
54	    const anthropic = getClient();
55	    if (!anthropic) return null;
56	
